/**
 * Executes the REAL Luau generated by every composite tool inside the standalone Luau VM
 * (luau CLI) against a small Roblox API stub (tests/luau/roblox-stub.luau).
 * This catches Luau syntax/runtime bugs that the JS mock MCP cannot see.
 * Set LUAU_BIN to the luau executable (default /data/tools/luau/luau); skipped if missing.
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { existsSync, readFileSync, writeFileSync, mkdtempSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { COMPOSITE_TOOLS, type CompositeContext, type SnapshotRecord } from "../../bridge/src/composites.js";
import { extractLuauPayload } from "../../bridge/src/luau.js";

const here = dirname(fileURLToPath(import.meta.url));
const LUAU = process.env.LUAU_BIN ?? "/data/tools/luau/luau";
const LUAU_COMPILE = process.env.LUAU_COMPILE_BIN ?? join(dirname(LUAU), "luau-compile");
const STUB = readFileSync(join(here, "../luau/roblox-stub.luau"), "utf8");
const skip = !existsSync(LUAU) ? `luau binary not found at ${LUAU}` : false;
const tool = (n: string) => {
  const t = COMPOSITE_TOOLS.find((x) => x.name === n);
  if (!t) throw new Error("no tool " + n);
  return t;
};

/** A scenario: sequence of composite calls sharing one DataModel (re-executed from scratch each step). */
class Scenario {
  chunks: string[] = [];
  snapshots = new Map<string, SnapshotRecord>();
  n = 0;
  dir = mkdtempSync(join(tmpdir(), "bw-luau-"));

  private program(): string {
    const body = this.chunks
      .map((c, i) => `do\n\tlocal __r = (function()\n${c}\nend)()\n\tprint("STEP${i}:" .. tostring(__r))\nend`)
      .join("\n");
    return STUB + "\n" + body + "\n";
  }

  private exec(): string[] {
    const file = join(this.dir, `p${this.chunks.length}.luau`);
    writeFileSync(file, this.program());
    if (existsSync(LUAU_COMPILE)) execFileSync(LUAU_COMPILE, ["--text", file], { stdio: "pipe" }); // syntax check
    const out = execFileSync(LUAU, [file], { encoding: "utf8", stdio: "pipe" });
    return out.split(/\r?\n/).filter((l) => /^STEP\d+:/.test(l));
  }

  ctx(): CompositeContext {
    return {
      runLuau: async (code) => {
        this.chunks.push(code);
        const lines = this.exec();
        const last = lines[this.chunks.length - 1];
        assert.ok(last, "no output for step " + (this.chunks.length - 1));
        const p = extractLuauPayload(last);
        assert.ok(p.found, "payload not found: " + last);
        if (!p.ok) throw new Error(p.error);
        return p.result;
      },
      callMcp: async () => ({ text: "", json: null, isError: false }),
      newId: (prefix) => `${prefix}_${++this.n}`,
      getSnapshot: (id) => this.snapshots.get(id),
      listSnapshots: () => [...this.snapshots.values()],
    };
  }

  async call(name: string, args: Record<string, unknown>): Promise<any> {
    const r: any = await tool(name).run(args, this.ctx());
    if (name === "take_snapshot") this.snapshots.set(r.snapshot.id, r.snapshot);
    return r;
  }
}

test("composite Luau runs in the real Luau VM", { skip }, async (t) => {
  const s = new Scenario();

  await t.test("get_game_tree", async () => {
    const r = await s.call("get_game_tree", { path: "game.Workspace", depth: 2 });
    const json = JSON.stringify(r);
    assert.match(json, /Baseplate/);
    assert.match(json, /Camera/);
  });

  await t.test("get_project_info", async () => {
    const r = await s.call("get_project_info", {});
    assert.match(JSON.stringify(r), /MenuCasov|ServerScriptService/);
  });

  await t.test("read_instance", async () => {
    const r = await s.call("read_instance", { path: "game.Workspace.Baseplate" });
    assert.match(JSON.stringify(r), /Part/);
  });

  await t.test("create_part with type coercion", async () => {
    const r = await s.call("create_part", { name: "AgentTestPart", size: [4, 1, 4], position: [0, 5, 0], color: [255, 0, 0], material: "Neon" });
    assert.equal(r.path, "game.Workspace.AgentTestPart");
    assert.deepEqual(r.propertyErrors, []);
    const read = await s.call("read_instance", { path: "game.Workspace.AgentTestPart" });
    assert.match(JSON.stringify(read), /Neon/);
  });

  await t.test("duplicate refused", async () => {
    await assert.rejects(() => s.call("create_part", { name: "AgentTestPart" }), /already exists/);
  });

  await t.test("modify_instance before/after", async () => {
    const r = await s.call("modify_instance", { path: "game.Workspace.AgentTestPart", properties: { Transparency: 0.5, Size: [8, 1, 8] }, attributes: { Owner: "agent" } });
    assert.equal(r.after.Transparency, 0.5);
    assert.equal(r.before.Transparency, 0);
    assert.deepEqual(r.errors, []);
  });

  await t.test("bad property reported, not thrown", async () => {
    const r = await s.call("modify_instance", { path: "game.Workspace.AgentTestPart", properties: { Anchored: "yes" } });
    assert.equal(r.errors.length, 1);
  });

  await t.test("create_ui tree", async () => {
    const r = await s.call("create_ui", {
      tree: {
        className: "ScreenGui", name: "ShopGui",
        children: [{ className: "Frame", name: "Panel", properties: { Size: { $type: "UDim2", value: [0.5, 0, 0.5, 0] }, BackgroundColor3: "#202030" },
          children: [{ className: "UICorner" }, { className: "TextButton", name: "Buy", properties: { Text: "Buy" } }] }],
      },
    });
    assert.equal(r.path, "game.StarterGui.ShopGui");
    assert.equal(r.created.length, 4);
    assert.deepEqual(r.propertyErrors, []);
  });

  await t.test("create_script + set_script_source", async () => {
    const r = await s.call("create_script", { parent: "game.ServerScriptService", name: "Shop", source: "print('shop')", className: "Script" });
    assert.match(JSON.stringify(r), /ServerScriptService\.Shop/);
    const u = await s.call("set_script_source", { path: "game.ServerScriptService.Shop", source: "print('shop v2')\nreturn 1" });
    assert.match(JSON.stringify(u), /Shop/);
    const read = await s.call("read_instance", { path: "game.ServerScriptService.Shop" });
    assert.match(JSON.stringify(read), /shop v2/);
  });

  await t.test("clone_instance", async () => {
    const r = await s.call("clone_instance", { path: "game.Workspace.AgentTestPart", name: "AgentTestPart2" });
    assert.match(JSON.stringify(r), /AgentTestPart2/);
  });

  await t.test("snapshot + restore", async () => {
    const snap = await s.call("take_snapshot", { paths: ["game.Workspace.AgentTestPart", "game.Workspace.NotYet"], label: "t" });
    const id = snap.snapshot.id;
    assert.equal(snap.snapshot.entries[0].saved, true);
    assert.equal(snap.snapshot.entries[1].absent, true);
    await s.call("delete_instance", { path: "game.Workspace.AgentTestPart" });
    await s.call("create_instance", { className: "Folder", parent: "game.Workspace", name: "NotYet" });
    const r = await s.call("restore_snapshot", { snapshotId: id });
    assert.deepEqual(r.restored, ["game.Workspace.AgentTestPart"]);
    assert.deepEqual(r.removed, ["game.Workspace.NotYet"]);
    assert.deepEqual(r.failed, []);
    const read = await s.call("read_instance", { path: "game.Workspace.AgentTestPart" });
    assert.match(JSON.stringify(read), /AgentTestPart/);
  });

  await t.test("delete + verify gone", async () => {
    await s.call("delete_instance", { path: "game.Workspace.AgentTestPart" });
    await assert.rejects(() => s.call("read_instance", { path: "game.Workspace.AgentTestPart" }), /not found|does not exist|no instance/i);
  });

  await t.test("delete_script", async () => {
    await s.call("delete_script", { path: "game.ServerScriptService.Shop" });
    await assert.rejects(() => s.call("delete_script", { path: "game.ServerScriptService.Main.Nope" }));
  });

  await t.test("invalid class -> clean error", async () => {
    await assert.rejects(() => s.call("create_instance", { className: "NotAClass", parent: "game.Workspace", name: "X" }), /Unable to create/);
  });
});
